    return_terms: Json;
    quantity: number;
    unit_price: number;
    discounts: Json;
    shipping_share: number;
    tax_share: number;
    paid_amount: number;
    refunded_amount: number;
    refund_status: string;
    state: string;
    state_before_request: string | null;
    shipment_id: string | null;
